    19	export class MqpubError extends Error {
    20	  constructor(readonly code: string, readonly exitStatus: number | null) {
    21	    super(`mqpub ${code} (exit ${exitStatus})`);
    22	  }
    23	}
    24	
    25	/** 사내 메시지 발행 CLI(mqpub 3.x) 래퍼 */
    26	export class MqpubClient {
    27	  constructor(private readonly bin: string, private readonly spoolDir: string) {}
    28	
    29	  private run(args: string[], input?: string): string {
    30	    const r = spawnSync(this.bin, args, {
    31	      input,
    32	      encoding: "utf8",
    33	      env: { ...process.env, MQPUB_SPOOL: this.spoolDir },
    34	    });
    35	    if (r.error) throw r.error;
    36	    if (r.status !== 0) {
    37	      const code = /E\d+/.exec(r.stderr)?.[0] ?? "E?";
    38	      throw new MqpubError(code, r.status);
    39	    }
    40	    return r.stdout;
    41	  }
    42	
    43	  /** 메시지들을 한 배치로 발행한다. */
    44	  publish(topic: string, messages: WireMessage[]): PublishResult {
    45	    if (messages.length === 0) return { accepted: 0, batch: 0 };
    46	    const body = messages.map((m) => `${m.key}\t${m.payload}`).join("\n") + "\n";
    47	    const out = this.run(["publish", "-t", topic], body);
    48	    const m = /^accepted (\d+) batch (\d+)$/m.exec(out);
    49	    if (!m) throw new MqpubError("unparsed-output", 0);
    50	    return { accepted: Number(m[1]), batch: Number(m[2]) };
    51	  }
    52	
    53	  /** offset 부터 끝까지 읽는다. */
    54	  consume(topic: string, fromOffset: number): ConsumedMessage[] {
    55	    const out = this.run(["consume", "-t", topic, "-o", String(fromOffset)]);
    56	    const rows: ConsumedMessage[] = [];
    57	    for (const line of out.split("\n")) {
    58	      if (line === "") continue;
    59	      const [off, key, ...rest] = line.split("\t");
    60	      rows.push({ offset: Number(off), key, payload: rest.join("\t") });
    61	    }
    62	    return rows;
    63	  }
    64	}
