     1	type Fn = () => void | Promise<void>;
     2	const registered: [string, Fn][] = [];
     3	const cleanups: (() => void)[] = [];
     4	
     5	export function test(name: string, fn: Fn): void {
     6	  registered.push([name, fn]);
     7	}
     8	
     9	export function onCleanup(fn: () => void): void {
    10	  cleanups.push(fn);
    11	}
    12	
    13	export function eq(actual: unknown, expected: unknown, label: string): void {
    14	  const a = JSON.stringify(actual);
    15	  const e = JSON.stringify(expected);
    16	  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
    17	}
    18	
    19	export async function run(): Promise<void> {
    20	  let failed = 0;
    21	  for (const [name, fn] of registered) {
    22	    try {
    23	      await fn();
    24	      console.log(`ok   - ${name}`);
    25	    } catch (e) {
    26	      failed++;
    27	      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
    28	    }
    29	  }
    30	  for (const c of cleanups) {
    31	    try { c(); } catch { /* ignore */ }
    32	  }
    33	  console.log(failed === 0 ? "all passed" : `${failed} failed`);
    34	  process.exitCode = failed === 0 ? 0 : 1;
