    37	 */
    38	export function formatOrderNo(channel: Channel, placedOn: string, seq: number, partner?: string): string {
    39	  const d = compactDate(placedOn);
    40	  if (channel === "direct") return `O${d}-${String(seq).padStart(5, "0")}`;
    41	  if (!partner || !/^[A-Z]{4}$/.test(partner)) throw new Error("invalid partner");
