/**
 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 *
 * mqpub 은 한 배치 안에서 키의 앞 16바이트가 같은 메시지를 중복으로 보고 첫 것만 저장한다.
 * 같은 날·같은 이벤트의 주문 키는 앞 16바이트가 모두 같으므로, 논리 키의 해시를 앞에 붙여
 * 메시지마다 앞부분이 달라지게 한다. 해시는 결정적이라 같은 알림은 늘 같은 키가 된다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const tag = createHash("sha1").update(logical).digest("hex").slice(0, 12);
  return `${tag}:${logical}`;
}

